import math
from datetime import datetime

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate
        self._collected = 0.0

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        duration_seconds = (exit - entry).total_seconds()
        duration_minutes = duration_seconds / 60.0

        # Stays longer than 24 hours incur a flat penalty.
        if duration_seconds > 24 * 60 * 60:
            return 200.00

        # Stays of at most 15 minutes are free.
        if duration_minutes <= 15:
            return 0.0

        # Charge every started hour as a full hour, including the first 15 minutes.
        hours = math.ceil(duration_seconds / 3600)
        total = hours * self.hourly_rate
        return round(total, 2)

    def estimate(self, hours: int) -> float:
        if hours < 0:
            raise ValueError("Hours cannot be negative.")

        duration_seconds = hours * 3600

        # Stays longer than 24 hours incur a flat penalty.
        if duration_seconds > 24 * 60 * 60:
            return 200.00

        # Stays of at most 15 minutes are free.
        if hours == 0:
            return 0.0

        return round(hours * self.hourly_rate, 2)

    def record(self, entry: datetime, exit: datetime) -> float:
        amount = self.fee(entry, exit)
        self._collected += amount
        return amount

    def total_collected(self) -> float:
        return round(self._collected, 2)
```

